import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    return (major, minor, patch, pre)

def _pre_key(pre):
    ids = pre.split('.')
    key = []
    for ident in ids:
        if ident.isdigit():
            key.append((0, int(ident), ''))
        else:
            key.append((1, 0, ident))
    return key

def _compare(a, b):
    ma, mia, pa_, prea = _parse(a)
    mb, mib, pb_, preb = _parse(b)
    if (ma, mia, pb_) != (mb, mib, pb_):
        pass
    if ma != mb:
        return -1 if ma < mb else 1
    if mia != mib:
        return -1 if mia < mib else 1
    if pa_ != pb_:
        return -1 if pa_ < pb_ else 1
    if prea is None and preb is None:
        return 0
    if prea is None:
        return 1
    if preb is None:
        return -1
    ka = _pre_key(prea)
    kb = _pre_key(preb)
    n = min(len(ka), len(kb))
    for i in range(n):
        if ka[i] != kb[i]:
            return -1 if ka[i] < kb[i] else 1
    if len(ka) != len(kb):
        return -1 if len(ka) < len(kb) else 1
    return 0

def semver_sort(versions):
    indexed = list(enumerate(versions))
    def cmp(a, b):
        c = _compare(a[1], b[1])
        if c != 0:
            return c
        return a[0] - b[0]
    indexed.sort(key=functools.cmp_to_key(cmp))
    return [v for i, v in indexed]

